export function totalThrough(n: number): number {
  let total = 0;
  for (let i = 1; i < n; i++) total += i;
  return total;
}

The function must satisfy:
  totalThrough(0) === 0
  totalThrough(1) === 1
  totalThrough(4) === 10  // 1+2+3+4
  totalThrough(10) === 55 // 1+…+10

